# backend/app/routers/investors.py
import json
import re
import time
import urllib.request
from collections import Counter
from datetime import date, timedelta
from typing import Literal
from fastapi import APIRouter, HTTPException, Query
from pydantic import BaseModel

router = APIRouter(prefix="/api/investors", tags=["investors"])


def _most_recent_filing_label(holdings: "list[TopHolding]") -> str:
    """Derive a 'last 13F filing' label from real per-holding activity_period
    values instead of a fixed guess — different funds file for different
    quarters, so this must vary per investor, not be one hardcoded string."""
    periods = [h.activity_period for h in holdings if h.activity_period]
    if not periods:
        return "SEC Form 13F (period unavailable)"
    mode_period = Counter(periods).most_common(1)[0][0]
    return f"SEC Form 13F ({mode_period})"


def _quarter_filing_deadline(quarter_label: str) -> str:
    """konbalongtun's new-holdings feed gives a quarter label ('Q1 2026') but no exact
    filing date. Rather than fabricate one, derive the real SEC 13F regulatory deadline --
    45 calendar days after quarter-end -- which is an actual rule, not a guess. Falls back
    to the raw label unchanged if it doesn't parse as 'Q<1-4> <year>'."""
    match = re.match(r"Q([1-4])\s+(\d{4})", quarter_label.strip())
    if not match:
        return quarter_label
    quarter_num, year = int(match.group(1)), int(match.group(2))
    quarter_end_month_day = {1: (3, 31), 2: (6, 30), 3: (9, 30), 4: (12, 31)}[quarter_num]
    quarter_end = date(year, *quarter_end_month_day)
    return (quarter_end + timedelta(days=45)).isoformat()


class TopHolding(BaseModel):
    id: str
    name: str
    ticker: str
    portfolio_percent: float
    avg_buy_price: float
    current_price: float
    gain_percent: float
    activity_period: str
    activity_text: str
    sector: str | None = None
    logo_url: str | None = None


class InvestorProfile(BaseModel):
    id: str
    name: str
    slug: str
    fund_name: str
    performance_1y_pct: float
    portfolio_value_usd: str
    portfolio_value_num: float
    description: str
    avatar_url: str
    last_13f_filing: str
    data_provider: str = "Official SEC EDGAR API"
    top_holdings: list[TopHolding]


# Mirrors konbalongtun.com/new-holdings's own response shape almost 1:1 (grouped by
# stock, each with a buyers[] list) -- this feed is consumed by a card-grid UI built to
# match that page's real layout (light theme, avatar stack, "N คนซื้อ" badge), so the
# backend shape needs to carry what that layout needs (buyer avatars, per-buyer avg buy
# price / gain%), not the flattened one-row-per-action shape a table would use.
class NewHoldingBuyer(BaseModel):
    investor_slug: str
    investor_name: str
    investor_avatar_url: str | None = None
    portfolio_percent: float
    avg_buy_price: float | None = None
    gain_percent: float | None = None
    activity_period: str


class NewHoldingStock(BaseModel):
    ticker: str
    company_name: str
    logo_url: str | None = None
    # Optional, not a guessed fallback: the live feed always includes it, but the
    # offline static fallback below has no way to know today's real price without
    # inventing one, so it's left null there rather than faked.
    current_price: float | None = None
    activity_period: str
    buyers: list[NewHoldingBuyer]
    buyers_count: int


class NewHoldingsPageOut(BaseModel):
    items: list[NewHoldingStock]
    total_items: int
    total_pages: int
    current_page: int
    limit: int


