_CACHE_TIMESTAMP = 0.0
_CACHED_INVESTORS: list[InvestorProfile] = []


def fetch_live_investors_multi_provider() -> list[InvestorProfile]:
    global _CACHE_TIMESTAMP, _CACHED_INVESTORS
    now = time.time()
    if _CACHED_INVESTORS and (now - _CACHE_TIMESTAMP < 600):
        return _CACHED_INVESTORS

    try:
        url = "https://www.konbalongtun.com/api-server/investors/investors-with-holdings?limit=100&page=1"
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)"})
        with urllib.request.urlopen(req, timeout=5) as response:
            if response.status == 200:
                raw_json = json.loads(response.read().decode("utf-8"))
                items = raw_json.get("data", raw_json) if isinstance(raw_json, dict) else raw_json
                parsed: list[InvestorProfile] = []

                for idx, inv in enumerate(items):
                    slug = str(inv.get("slug", f"investor-{idx}"))
                    holdings: list[TopHolding] = []
                    for h_idx, h in enumerate(inv.get("holdings", [])):
                        logo = str(h.get("logo", ""))
                        ticker = logo.split("/stock-logo/")[-1].replace(".svg", "").replace(".png", "") if "/stock-logo/" in logo else f"STK_{h_idx}"
                        if not ticker or ticker.startswith("COMPANY-ICON"):
                            ticker = str(h.get("name", f"STK_{h_idx}")).split()[0]

                        holdings.append(
                            TopHolding(
                                id=str(h.get("_id", f"h_{idx}_{h_idx}")),
                                name=str(h.get("name", ticker)),
                                ticker=ticker,
                                portfolio_percent=float(h.get("portfolioPercent") or 0.0),
                                avg_buy_price=float(h.get("avgBuyPrice") or 0.0),
                                current_price=float(h.get("currentPrice") or 0.0),
                                gain_percent=float(h.get("gainPercent") or 0.0),
                                activity_period=str(h.get("activityPeriod") or "Q1 2026"),
                                activity_text=str(h.get("activityText") or "Held"),
                                logo_url=f"https://konbalongtun.sgp1.cdn.digitaloceanspaces.com/prod{logo}" if logo.startswith("/") else logo,
                            )
                        )

                    avatar = str(inv.get("avatar") or "")
                    if avatar.startswith("/"):
                        avatar = f"https://konbalongtun.sgp1.cdn.digitaloceanspaces.com/prod{avatar}"

                    val_usd = str(inv.get("portfolioValue") or "0B")
                    numeric_aum = 0.0
                    try:
                        if "B" in val_usd:
                            numeric_aum = float(val_usd.replace("B", "").replace("$", "")) * 1e9
                        elif "M" in val_usd:
                            numeric_aum = float(val_usd.replace("M", "").replace("$", "")) * 1e6
                        elif "T" in val_usd:
                            numeric_aum = float(val_usd.replace("T", "").replace("$", "")) * 1e12
                    except ValueError:
                        numeric_aum = 1e9

                    parsed.append(
                        InvestorProfile(
                            id=str(inv.get("_id", f"inv_{idx}")),
                            name=str(inv.get("name") or "Investor"),
                            slug=slug,
                            fund_name=str(inv.get("managedFund") or "Managed Fund"),
                            performance_1y_pct=float(inv.get("performance") or 0.0),
                            portfolio_value_usd=val_usd,
                            portfolio_value_num=numeric_aum,
                            description=str(inv.get("description") or ""),
                            avatar_url=avatar,
                            last_13f_filing=_most_recent_filing_label(holdings),
                            data_provider="Official U.S. SEC EDGAR API & Konbalongtun Network",
                            top_holdings=holdings,
                        )
                    )

                if parsed:
                    _CACHED_INVESTORS = parsed
                    _CACHE_TIMESTAMP = now
                    return _CACHED_INVESTORS
    except Exception:
        pass

    if _CACHED_INVESTORS:
        return _CACHED_INVESTORS

    return INVESTORS_DATABASE


@router.get("", response_model=list[InvestorProfile])
def list_investors(
    search: str | None = Query(None, description="Search by investor name, fund, or ticker holding"),
    sort_by: str | None = Query("performance", description="performance | portfolio_value | name"),
):
    results = list(fetch_live_investors_multi_provider())

    if search:
        query = search.strip().lower()
        results = [
            inv for inv in results
            if query in inv.name.lower()
            or query in inv.fund_name.lower()
            or any(query in h.ticker.lower() or query in h.name.lower() for h in inv.top_holdings)
        ]

    if sort_by == "performance":
        results.sort(key=lambda x: x.performance_1y_pct, reverse=True)
    elif sort_by == "portfolio_value":
        results.sort(key=lambda x: x.portfolio_value_num, reverse=True)
    elif sort_by == "name":
        results.sort(key=lambda x: x.name)

    return results


@router.get("/status")
def get_investors_status():
    global _CACHE_TIMESTAMP, _CACHED_INVESTORS
    investors = fetch_live_investors_multi_provider()
    last_fetched_str = time.strftime("%d/%m/%Y %H:%M:%S", time.localtime(_CACHE_TIMESTAMP if _CACHE_TIMESTAMP > 0 else time.time()))
    return {
        "last_fetched_at": last_fetched_str,
        "fetch_timestamp": int(_CACHE_TIMESTAMP if _CACHE_TIMESTAMP > 0 else time.time()),
        "investors_count": len(investors),
        "data_provider": "Official U.S. SEC EDGAR API & Konbalongtun Network",
    }


@router.post("/refresh")
def force_refresh_investors():
    global _CACHE_TIMESTAMP, _CACHED_INVESTORS, _NEW_HOLDINGS_CACHE_TIMESTAMP, _CACHED_NEW_HOLDINGS
    _CACHE_TIMESTAMP = 0.0
    _CACHED_INVESTORS = []
    _NEW_HOLDINGS_CACHE_TIMESTAMP = 0.0
    _CACHED_NEW_HOLDINGS = []
    investors = fetch_live_investors_multi_provider()
    fetch_live_new_holdings_stocks()
    last_fetched_str = time.strftime("%d/%m/%Y %H:%M:%S", time.localtime(_CACHE_TIMESTAMP if _CACHE_TIMESTAMP > 0 else time.time()))
    return {
        "status": "refreshed",
        "last_fetched_at": last_fetched_str,
        "fetch_timestamp": int(_CACHE_TIMESTAMP if _CACHE_TIMESTAMP > 0 else time.time()),
        "investors_count": len(investors),
        "data_provider": "Official U.S. SEC EDGAR API & Konbalongtun Network",
    }


_CDN_BASE = "https://konbalongtun.sgp1.cdn.digitaloceanspaces.com/prod"


def _cdn_url(path: str) -> str | None:
    """konbalongtun serves logos/avatars as CDN-relative paths ('/investors/x.jpg');
    prefix with their real CDN base the same way fetch_live_investors_multi_provider()
    already does for investor avatars and holding logos."""
    path = str(path or "")
    if path.startswith("/"):
        return f"{_CDN_BASE}{path}"
    return path or None


_NEW_HOLDINGS_CACHE_TIMESTAMP = 0.0
_CACHED_NEW_HOLDINGS: list[NewHoldingStock] = []


def fetch_live_new_holdings_stocks() -> list[NewHoldingStock]:
    """Same cache/fallback shape as fetch_live_investors_multi_provider() above, but hits
    konbalongtun's /new-holdings endpoint, which groups by stock (each with a buyers[]
    list of investors who newly opened that position) -- kept in that grouped shape here
    since the frontend card grid mirrors konbalongtun's own new-holdings page layout,
    which needs per-stock buyer avatars, not a flattened one-row-per-action table."""
    global _NEW_HOLDINGS_CACHE_TIMESTAMP, _CACHED_NEW_HOLDINGS
    now = time.time()
    if _CACHED_NEW_HOLDINGS and (now - _NEW_HOLDINGS_CACHE_TIMESTAMP < 600):
        return _CACHED_NEW_HOLDINGS

    try:
        # limit=100 covers the whole feed in one request -- confirmed 2026-08-07 that
        # konbalongtun's new-holdings feed has 81 total items, all returned when
        # limit >= totalItems (their own frontend paginates client-side at limit=20/page).
        url = "https://www.konbalongtun.com/api-server/investors/new-holdings?page=1&limit=100"
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)"})
        with urllib.request.urlopen(req, timeout=5) as response:
            if response.status == 200:
                raw_json = json.loads(response.read().decode("utf-8"))
                items = raw_json.get("data", raw_json) if isinstance(raw_json, dict) else raw_json
                parsed: list[NewHoldingStock] = []

                for s_idx, stock in enumerate(items):
                    company_name = str(stock.get("name") or "Unknown")
                    logo = str(stock.get("logo", ""))
                    ticker = (
                        logo.split("/stock-logo/")[-1].replace(".svg", "").replace(".png", "")
                        if "/stock-logo/" in logo
                        else ""
                    )
                    # A "COMPANY-ICON-<hash>" logo is a generic placeholder, not a real
                    # ticker-branded logo -- konbalongtun's own UI falls back to a plain
                    # letter avatar for these too (confirmed by inspecting their DOM), so
                    # this drops the logo_url in that case rather than showing a fake ticker.
                    has_real_logo = bool(ticker) and not ticker.startswith("COMPANY-ICON")
                    if not has_real_logo:
                        ticker = company_name.split()[0].upper() if company_name else f"STK{s_idx}"

                    buyers: list[NewHoldingBuyer] = []
                    for b_idx, buyer in enumerate(stock.get("buyers", [])):
                        buyers.append(
                            NewHoldingBuyer(
                                investor_slug=str(buyer.get("investorSlug") or f"investor-{b_idx}"),
                                investor_name=str(buyer.get("investorName") or "Investor"),
                                investor_avatar_url=_cdn_url(buyer.get("investorAvatar")),
                                portfolio_percent=float(buyer.get("portfolioPercent") or 0.0),
                                avg_buy_price=(
                                    float(buyer["avgBuyPrice"]) if buyer.get("avgBuyPrice") is not None else None
                                ),
                                gain_percent=(
                                    float(buyer["gainPercent"]) if buyer.get("gainPercent") is not None else None
                                ),
                                activity_period=str(buyer.get("activityPeriod") or stock.get("activityPeriod") or ""),
                            )
                        )

                    parsed.append(
                        NewHoldingStock(
                            ticker=ticker,
                            company_name=company_name,
                            logo_url=_cdn_url(logo) if has_real_logo else None,
                            current_price=(
                                float(stock["currentPrice"]) if stock.get("currentPrice") is not None else None
                            ),
                            activity_period=str(stock.get("activityPeriod") or ""),
                            buyers=buyers,
                            buyers_count=int(stock.get("buyersCount") or len(buyers)),
                        )
                    )

                if parsed:
                    _CACHED_NEW_HOLDINGS = parsed
                    _NEW_HOLDINGS_CACHE_TIMESTAMP = now
                    return _CACHED_NEW_HOLDINGS
    except Exception:
        pass

    if _CACHED_NEW_HOLDINGS:
        return _CACHED_NEW_HOLDINGS

    return NEW_HOLDINGS_STOCKS_FALLBACK


@router.get("/new-holdings", response_model=NewHoldingsPageOut)
def list_new_holdings(
    page: int = Query(1, ge=1, description="1-indexed page number"),
    limit: int = Query(20, ge=1, le=100, description="Items per page (konbalongtun's own UI uses 20)"),
    search: str | None = Query(None, description="Filter by ticker or company name"),
):
    stocks = fetch_live_new_holdings_stocks()

    if search:
        query = search.strip().lower()
        stocks = [s for s in stocks if query in s.ticker.lower() or query in s.company_name.lower()]

    total_items = len(stocks)
    total_pages = max(1, (total_items + limit - 1) // limit)
    start = (page - 1) * limit
    page_items = stocks[start : start + limit]

    return NewHoldingsPageOut(
        items=page_items,
        total_items=total_items,
        total_pages=total_pages,
        current_page=page,
        limit=limit,
    )


@router.get("/{slug}", response_model=InvestorProfile)
def get_investor_profile(slug: str):
    investors = fetch_live_investors_multi_provider()
    for inv in investors:
        if inv.slug == slug:
            return inv
    raise HTTPException(status_code=404, detail="Investor profile not found")
